import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { AlertService } from 'src/app/services/alert.service';
import { EmisService } from 'src/app/services/emis/emis.service';
import { UserService } from 'src/app/services/emis/user.service';
import { UserSessionService } from 'src/app/services/usersession.service';

@Component({
  selector: 'app-other-district-survey',
  templateUrl: './other-district-survey.page.html',
  styleUrls: ['./other-district-survey.page.scss'],
})
export class OtherDistrictSurveyPage implements OnInit {
  distId: any;
  otherStudents: any=[];
  show: boolean
  teacher_id: number;
  activeSchoolId: any;
  routeData: any;
  paramsId: any;
  pageId: any;
  active: any;
  blockId: any;
  activeSchollName: any;
  blocklistActive: boolean;


  constructor(private alertService:AlertService,private userService: UserService,private emisService: EmisService,private userSessionService: UserSessionService,public router: Router, private route: ActivatedRoute,) { }

  ngOnInit() {
  }

  ionViewDidEnter() {
    this.distId = this.userSessionService.district_id();
    this.teacher_id = this.userSessionService.teacher_id();
    this.routeData = this.route.snapshot;
    this.paramsId = this.routeData.queryParams.Id;
    this.pageId = this.routeData.queryParams.page;
    this.active = this.routeData.queryParams.active;
    this.getUserDetails();
    console.log('id3',this.paramsId)

      }

      getUserDetails() {  
        this.userService.getOoscUserDetails(this.teacher_id).subscribe(res => { 
          console.log("result",res);
          if (res.dataStatus == true ) {
            var uerDetails = res.result;
            if (uerDetails.length > 0) {
                this.getOoscOtherDistrict(uerDetails[0].district_id);
                console.log('dissssss',uerDetails[0].district_id)
            } else {
              this.blocklistActive = false;
            }
          } else {
            this.alertService.error("Something went wrong");
          }
        });
    }
  getOoscOtherDistrict(distId){
    this.emisService.GetOoscOtherDistrict(distId).subscribe((res) => {
      if (res.dataStatus) {
        this.show = false;
        this.otherStudents = res.result;
        console.log('>>>>>>>>>>>hey',this.otherStudents)
    var student =this.otherStudents;
    console.log('>>>>>>>>>>>uuuuu',student)

      }else {
        console.log('>>false')
        this.show = true;
      }
    });
  }



  goHome(){
    this.router.navigate(['/tabs/oosctype']);
  }
  goToOoscSurvey(student) {
    debugger
    // console.log('st',student)

    console.log('stuuuuu',student.student_id)
    this.router.navigate(['/tabs/ooscquestions'], { queryParams: { 'studentName': student.name, 'studentEmisNo': student.unique_id_no, 'Address': student.house_address, 'id': student.student_id, 'teacher': this.teacher_id, 'school': this.activeSchoolId, 'block': this.blockId, 'Id': this.paramsId ,'schoolname': this.activeSchollName,'active':this.active}, skipLocationChange: false });
  }
}
